                pendingServices.add(Pair(pkg, s))
            }
        }
        for ((pkg, serviceBytes) in pendingServices) {
            parseService(pkg, serviceBytes, file)
        }
        return file
    }

    private fun parseMessage(prefix: String, data: ByteArray, file: FileModel) {
